#include <iostream>

#define RECT_AREA(x, y) \
    ((x) * (y))

// Safe C++17 alternative
template <typename T>
constexpr auto safeSquare(T x) noexcept {
    return x * x;
}

int main() {
    int w = 3, h = 5;
    std::cout << "RECT_AREA(w+1, h+2) = " << RECT_AREA(w + 1, h + 2) << "\n";

#undef RECT_AREA

    int val = 4;
    // Calling safe C++ inline/constexpr function
    int res = safeSquare(++val); // val becomes 5, evaluated exactly once
    std::cout << "safeSquare(++val) = " << res << ", val = " << val << "\n";

    return 0;
}

